  "accion": "CALCULAR",
  "solicitudes": [
    {
      "recurso": "sensores",
      "cantidad": null,
      "unidad": "unidades",
      "evidencia": "4 estuches de 6 sensores cada uno",
      "presentacion_logistica": {
        "cantidad_envases": 4,
        "envase": "estuche",
        "contenido_por_envase": 6,
        "unidad_contenido": "unidades"
      },
      "calculo": {
        "tipo": "PRODUCTO",
        "operandos": [
          4,
          6
        ],
        "unidad_resultado": "unidades",
        "evidencia": "4 estuches de 6 sensores cada uno"
      }
    }
  ],
  "exclusiones": [],
